package com.ferreteriahuaman.service;
import com.ferreteriahuaman.dto.SaleModels.*;import com.ferreteriahuaman.dto.SaleHistoryModels.*;import com.ferreteriahuaman.dto.CatalogModels.Page;import com.ferreteriahuaman.repository.*;import com.ferreteriahuaman.security.*;import com.ferreteriahuaman.security.AuthModels.Identity;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.*;import java.math.BigDecimal;import java.util.*;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.transaction.annotation.Isolation;
@Service @Profile("db") public class SaleHistoryService {
 private final SaleRepository repo;private final CashRepository cash;private final BusinessTransactions tx;private final AuthStore auth;private final ObjectMapper mapper;
 public SaleHistoryService(SaleRepository repo,CashRepository cash,BusinessTransactions tx,AuthStore auth,ObjectMapper mapper){this.repo=repo;this.cash=cash;this.tx=tx;this.auth=auth;this.mapper=mapper;}
 private String json(Object value){try{return mapper.writeValueAsString(value);}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException("No se pudo preparar la operación");}}
 private Map<String,Object> header(long id,boolean lock){var v=repo.get(id,lock).orElseThrow(()->new AuthFailure(404,"Venta no encontrada"));if(!Set.of("CONFIRMADA","ANULADA").contains(v.get("estado")))throw new AuthFailure(404,"La venta no está registrada en el historial");return v;}
 private void version(Map<String,Object> v,LocalDateTime expected){if(!LocalDateTime.parse(v.get("version").toString()).equals(expected))throw new AuthFailure(409,"La venta cambió. Vuelve a cargarla antes de continuar");}
 public Page<Map<String,Object>> list(String q,LocalDate from,LocalDate to,String type,String state,Long seller,int page,int size){if(q.length()>100||page<0||page>1000000||size<1||size>100||!type.matches("B|F|N|^$")||!state.matches("CONFIRMADA|ANULADA|^$")||seller!=null&&seller<1||from!=null&&to!=null&&from.isAfter(to))throw new AuthFailure(400,"Revisa los filtros y la paginación");return repo.history(q.strip(),from,to,type,state,seller,page,size);}
 public List<Map<String,Object>> sellers(){return repo.sellers();}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ) public Details details(long id){return new Details(header(id,false),repo.lines(id),repo.payments(id),repo.receipt(id));}
 public Details print(Identity a,String pc,long id,Key i){return tx.write(a,pc,"VEN.REIMPRIMIR",()->{repo.lockKey(i.clave());header(id,true);var previous=repo.replay("VEN.REIMPRIMIR_API","IMPRIMIR:"+i.clave(),a.id(),json(Map.of("venta",id)));if(previous.isEmpty())repo.audit(a.id(),"VEN.REIMPRIMIR_API",id,"IMPRIMIR:"+i.clave(),json(Map.of("venta",id)));return details(id);});}
 public Details copy(Identity a,String pc,long id,Copy i){return tx.write(a,pc,"VEN.COPIAR",()->{if(!auth.permissions(a.id()).contains("VEN.VENDER"))throw new AuthFailure(403,"Necesitas permiso para preparar ventas");repo.lockKey(i.clave());String request=json(Map.of("venta",id,"version",i.version()));var previous=repo.replay("VEN.COPIAR_API","COPIA:"+i.clave(),a.id(),request);if(previous.isPresent()){long saved=previous.get();return new Details(repo.get(saved,false).orElseThrow(),repo.lines(saved),repo.payments(saved),repo.receipt(saved));}var current=cash.current();if(current.caja()==null||!current.caja().estado().equals("ABIERTA")||!current.caja().fecha().equals(current.fechaServidor()))throw new AuthFailure(409,"Abre la caja de hoy antes de copiar una venta");repo.lockCash(current.caja().id());var source=header(id,true);version(source,i.version());if(!source.get("estado").equals("CONFIRMADA"))throw new AuthFailure(409,"Solo puedes copiar una venta confirmada");var lines=repo.lines(id).stream().map(l->new Line(((Number)l.get("presentacionId")).longValue(),new BigDecimal(l.get("cantidad").toString()),((Number)l.get("piezas")).intValue())).toList();var input=new Create((Long)source.get("clienteId"),source.get("tipo").toString(),false,i.clave(),lines);long saved=repo.copy(current.caja().id(),a.id(),id,input);for(var l:lines)repo.add(saved,l);if(repo.lines(saved).size()!=lines.size()||lines.isEmpty())throw new AuthFailure(409,"Revisa los productos y presentaciones de la venta original");repo.audit(a.id(),"VEN.COPIAR_API",saved,"COPIA:"+i.clave(),request);return new Details(repo.get(saved,false).orElseThrow(),repo.lines(saved),repo.payments(saved),null);});}
 public Details cancel(Identity a,String pc,long id,Cancel i){return tx.write(a,pc,"VEN.ANULAR",()->{if(!a.rol().equals("ADM"))throw new AuthFailure(403,"Solo administración puede anular ventas");var initial=header(id,false);repo.lockCash(((Number)initial.get("cajaId")).longValue());var v=header(id,true);if(!v.get("estado").equals("ANULADA"))version(v,i.version());var plans=new ArrayList<Map<String,Object>>();int pieces=0;for(var r:i.retornos()){var units=new ArrayList<Map<String,Object>>();for(var p:r.unidades()){if(++pieces>1000)throw new AuthFailure(400,"El retorno admite como máximo 1 000 piezas");var unit=new LinkedHashMap<String,Object>();unit.put("condicion",p.condicion());unit.put("cantidad",p.cantidad());if(p.presentacionId()!=null)unit.put("id_presentacion",p.presentacionId());units.add(unit);}plans.add(Map.of("id_detalle_venta",r.lineaId(),"unidades",units));}var references=new LinkedHashMap<String,String>();if(i.referenciaYape()!=null)references.put("YAPE",i.referenciaYape());if(i.referenciaDebito()!=null)references.put("DEBITO",i.referenciaDebito());repo.cancel(id,i.clave(),i.motivo(),i.retornoConfirmado(),json(plans),json(references));return details(id);});}
}
